//! Real tablet thumbnails, not snapshots generated by this renderer.
//! See conformance/rendering/tablet-thumbnails/eink-sync/README.md.

use std::path::PathBuf;

use remarkable_rm::{RenderOptions, parse_page, render_page};
use tiny_skia::{Color, Pixmap};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

// The upstream comparisons use grayscale. All pixels are opaque; an integer
// channel average is sufficient for these monochrome pencil references.
fn gray(pixel: tiny_skia::PremultipliedColorU8) -> u32 {
    (u32::from(pixel.red()) + u32::from(pixel.green()) + u32::from(pixel.blue())) / 3
}

fn quality_score(expected: &Pixmap, actual: &Pixmap) -> f64 {
    assert_eq!(expected.width(), actual.width());
    assert_eq!(expected.height(), actual.height());
    let width = usize::try_from(expected.width()).unwrap();
    let height = usize::try_from(expected.height()).unwrap();
    let total: u32 = expected
        .pixels()
        .iter()
        .zip(actual.pixels())
        .map(|(&a, &b)| gray(a).abs_diff(gray(b)))
        .sum();
    let pixel_count = expected.width() * expected.height();
    let mae = f64::from(total) / f64::from(pixel_count);

    // Match upstream's 8x8 block-mean difference, including its exclusive end.
    // Upstream calls this "ssim", but it is not the SSIM algorithm.
    let mut block_difference = 0.0;
    let mut blocks = 0_u32;
    for y in (0..height - 8).step_by(8) {
        for x in (0..width - 8).step_by(8) {
            let mut a = 0_u32;
            let mut b = 0_u32;
            for dy in 0..8 {
                for dx in 0..8 {
                    let i = (y + dy) * width + x + dx;
                    a += gray(expected.pixels()[i]);
                    b += gray(actual.pixels()[i]);
                }
            }
            block_difference += f64::from(a.abs_diff(b)) / 64.0;
            blocks += 1;
        }
    }
    mae.midpoint(block_difference / f64::from(blocks))
}

/// Fraction of source ink with matching ink within two pixels in the target.
/// Calling in both directions detects missing strokes and excess stroke width.
fn ink_coverage(source: &Pixmap, target: &Pixmap) -> f64 {
    assert_eq!(source.width(), target.width());
    assert_eq!(source.height(), target.height());
    let width = usize::try_from(source.width()).unwrap();
    let height = usize::try_from(source.height()).unwrap();
    let mut ink = 0_u32;
    let mut matched = 0_u32;
    for y in 0..height {
        for x in 0..width {
            if gray(source.pixels()[y * width + x]) >= 240 {
                continue;
            }
            ink += 1;
            let nearby = (y.saturating_sub(2)..=(y + 2).min(height - 1)).any(|ny| {
                (x.saturating_sub(2)..=(x + 2).min(width - 1))
                    .any(|nx| gray(target.pixels()[ny * width + nx]) < 240)
            });
            if nearby {
                matched += 1;
            }
        }
    }
    if ink == 0 {
        1.0
    } else {
        f64::from(matched) / f64::from(ink)
    }
}

fn save_comparison(name: &str, expected: &Pixmap, actual: &Pixmap) -> PathBuf {
    let output = root().join("target/conformance/rendering").join(name);
    std::fs::create_dir_all(&output).unwrap();
    expected.save_png(output.join("expected.png")).unwrap();
    actual.save_png(output.join("actual.png")).unwrap();
    let mut diff = Pixmap::new(expected.width(), expected.height()).unwrap();
    for ((out, a), b) in diff
        .data_mut()
        .as_chunks_mut::<4>()
        .0
        .iter_mut()
        .zip(expected.data().as_chunks::<4>().0.iter())
        .zip(actual.data().as_chunks::<4>().0.iter())
    {
        out.copy_from_slice(&[
            a[0].abs_diff(b[0]),
            a[1].abs_diff(b[1]),
            a[2].abs_diff(b[2]),
            255,
        ]);
    }
    diff.save_png(output.join("diff.png")).unwrap();
    output
}

fn assert_visual_match(name: &str, expected: &Pixmap, actual: &Pixmap, maximum_score: f64) {
    let score = quality_score(expected, actual);
    let recall = ink_coverage(expected, actual);
    let precision = ink_coverage(actual, expected);
    let metrics = format!(
        "score={score:.4} (max {maximum_score}), ink recall={recall:.4}, precision={precision:.4} (min 0.90 each)"
    );
    eprintln!("{name}: {metrics}");
    if score > maximum_score || recall < 0.90 || precision < 0.90 {
        let output = save_comparison(name, expected, actual);
        panic!("{name}: got {metrics}; images: {}", output.display());
    }
}

fn thumbnail(name: &str) -> (Pixmap, Vec<u8>) {
    let case = root()
        .join("conformance/rendering/tablet-thumbnails/eink-sync")
        .join(name);
    let expected = Pixmap::load_png(case.join(format!("{name}.png"))).unwrap();
    assert_eq!((expected.width(), expected.height()), (384, 512));
    let bytes = std::fs::read(case.join(format!("{name}.rm"))).unwrap();
    (expected, bytes)
}

fn rendered_thumbnail(name: &str) -> (Pixmap, Pixmap) {
    let (expected, bytes) = thumbnail(name);
    let page = parse_page(&bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
    let png = render_page(
        &page,
        RenderOptions {
            width: 384,
            height: 512,
        },
    )
    .unwrap();
    let actual = Pixmap::decode_png(&png).unwrap();
    (expected, actual)
}

fn compare_thumbnail(name: &str, maximum_score: f64) {
    let (expected, actual) = rendered_thumbnail(name);
    assert_visual_match(name, &expected, &actual, maximum_score);
}

fn assert_thumbnail_ink_geometry(name: &str) {
    let (expected, actual) = rendered_thumbnail(name);
    let recall = ink_coverage(&expected, &actual);
    let precision = ink_coverage(&actual, &expected);
    if recall < 0.90 || precision < 0.90 {
        let output = save_comparison(name, &expected, &actual);
        panic!(
            "{name}: expected ink recall/precision >= 0.90, got {recall:.4}/{precision:.4}; images: {}",
            output.display()
        );
    }
}

#[test]
fn heavy_pencil_preserves_reference_ink_geometry() {
    assert_thumbnail_ink_geometry("quicksheets-p2");
}

#[test]
fn mixed_pressure_pencil_preserves_reference_ink_geometry() {
    assert_thumbnail_ink_geometry("quicksheets-p3");
}

#[test]
fn heavy_pencil_matches_tablet_thumbnail() {
    compare_thumbnail("quicksheets-p2", 20.0);
}

#[test]
fn mixed_pressure_pencil_matches_tablet_thumbnail() {
    compare_thumbnail("quicksheets-p3", 10.0);
}

#[test]
#[ignore = "invalid upstream pairing: PNG contains different text and additional strokes, and its template is missing; see official sample README"]
fn official_export_matches_sample_page() {
    let case = root().join("conformance/rendering/tablet-exports/remarkable-rm/sample-page");
    let expected = Pixmap::load_png(case.join("sample-tablet-export.png")).unwrap();
    let bytes = std::fs::read(case.join("sample-page.rm")).unwrap();
    let page = parse_page(&bytes).unwrap_or_else(|error| {
        let output = root().join("target/conformance/rendering/official-sample");
        std::fs::create_dir_all(&output).unwrap();
        expected.save_png(output.join("expected.png")).unwrap();
        std::fs::write(output.join("parse-error.txt"), error.to_string()).unwrap();
        panic!(
            "official sample: got {error}; evidence: {}",
            output.display()
        )
    });
    let png = render_page(
        &page,
        RenderOptions {
            width: expected.width(),
            height: expected.height(),
        },
    )
    .unwrap();
    let actual = Pixmap::decode_png(&png).unwrap();
    assert_visual_match("official-sample", &expected, &actual, 10.0);
}

#[test]
fn references_match_themselves_and_reject_blank_output() {
    for name in ["quicksheets-p2", "quicksheets-p3"] {
        let (expected, bytes) = thumbnail(name);
        parse_page(&bytes).unwrap_or_else(|error| panic!("{name}: got {error}"));
        assert_visual_match(name, &expected, &expected, 0.0);
        let mut blank = Pixmap::new(expected.width(), expected.height()).unwrap();
        blank.fill(Color::WHITE);
        assert!(
            ink_coverage(&expected, &blank) < 0.90,
            "{name}: blank output passed ink recall"
        );
    }
}

#[test]
fn ink_metric_detects_missing_strokes_despite_white_margins() {
    let mut expected = Pixmap::new(384, 512).unwrap();
    expected.fill(Color::WHITE);
    for x in [10, 100] {
        expected.pixels_mut()[100 * 384 + x] =
            tiny_skia::PremultipliedColorU8::from_rgba(0, 0, 0, 255).unwrap();
    }
    let mut actual = expected.clone();
    actual.pixels_mut()[100 * 384 + 100] =
        tiny_skia::PremultipliedColorU8::from_rgba(255, 255, 255, 255).unwrap();
    assert!(
        quality_score(&expected, &actual) < 1.0,
        "white margins mask the missing dot"
    );
    assert!(ink_coverage(&expected, &actual) < 0.90);
    assert!(ink_coverage(&actual, &expected) >= 0.90);
}

#[test]
fn ink_metric_tolerates_two_pixels_but_rejects_larger_displacement() {
    let mut expected = Pixmap::new(32, 32).unwrap();
    expected.fill(Color::WHITE);
    let black = tiny_skia::PremultipliedColorU8::from_rgba(0, 0, 0, 255).unwrap();
    expected.pixels_mut()[16 * 32 + 16] = black;
    for (offset, matches) in [(2, true), (3, false)] {
        let mut actual = Pixmap::new(32, 32).unwrap();
        actual.fill(Color::WHITE);
        actual.pixels_mut()[16 * 32 + 16 + offset] = black;
        assert_eq!(
            ink_coverage(&expected, &actual) >= 0.90,
            matches,
            "offset={offset}"
        );
    }
}
